// Demo mode: answers the /api/auth requests in the browser (localStorage),
// so the live demo works without running the Node server.
const USERS = 'demo-users';
const read = () => JSON.parse(localStorage.getItem(USERS) || '[]');
const write = (u) => localStorage.setItem(USERS, JSON.stringify(u));
const reply = (status, body) =>
  Promise.resolve(new Response(JSON.stringify(body), { status, headers: { 'Content-Type': 'application/json' } }));

const realFetch = window.fetch.bind(window);
window.fetch = (url, options = {}) => {
  const path = String(url);
  if (!path.includes('/api/auth/')) return realFetch(url, options);
  const body = options.body ? JSON.parse(options.body) : {};
  const token = ((options.headers || {}).Authorization || '').replace('Bearer ', '');
  const users = read();

  if (path.endsWith('/register')) {
    if (users.find((u) => u.email === body.email)) return reply(400, { error: 'A user with this email already exists.' });
    const user = { id: Date.now(), ...body };
    write([...users, user]);
    return reply(200, { authtoken: `demo-${user.id}`, name: user.name, phone: user.phone });
  }
  if (path.endsWith('/login')) {
    const user = users.find((u) => u.email === body.email && u.password === body.password);
    if (!user) return reply(400, { error: 'Invalid email or password.' });
    return reply(200, { authtoken: `demo-${user.id}`, name: user.name, phone: user.phone });
  }
  if (path.endsWith('/user')) {
    const user = users.find((u) => `demo-${u.id}` === token);
    if (!user) return reply(401, { error: 'Please log in again.' });
    if ((options.method || 'GET') === 'PUT') {
      user.name = body.name; user.phone = body.phone; write(users);
    }
    return reply(200, { name: user.name, email: user.email, phone: user.phone });
  }
  return reply(404, { error: 'Not found' });
};
